<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { guardarTipoTransaccion, listarTiposTransaccion, type TipoTransaccion } from '../services/tiposTransaccion'
const rows=ref<TipoTransaccion[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const form=reactive({nombre:'',grupo:'' as ''|'i'|'s',orden_compra:false,pedido:false,documento:false,requiere_asiento_contable:false,requiere_almacen_destino:false,estado:true})
async function load(next=1){page.value=next;loading.value=true;error.value='';try{const r=await listarTiposTransaccion(criterio.value,next);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(item?:TipoTransaccion){editing.value=item?.id||null;Object.assign(form,{nombre:item?.nombre||'',grupo:item?.grupo||'',orden_compra:item?.orden_compra||false,pedido:item?.pedido||false,documento:item?.documento||false,requiere_asiento_contable:item?.requiere_asiento_contable||false,requiere_almacen_destino:item?.requiere_almacen_destino||false,estado:item?.estado??true});modal.value=true}
function validate(){if(!form.grupo)return 'Seleccione el tipo de transacción.';if(!form.nombre.trim())return 'El nombre de la transacción es obligatorio.';if(form.orden_compra&&form.pedido)return 'La transacción no debe exigir simultáneamente orden de compra y pedido.';return ''}
async function save(){const issue=validate();if(issue){error.value=issue;return}saving.value=true;try{await guardarTipoTransaccion(editing.value,{...form,grupo:form.grupo as 'i'|'s'});modal.value=false;success.value=`Tipo de transacción ${editing.value?'actualizado':'creado'} correctamente.`;await load(editing.value?page.value:1)}catch(e){error.value=message(e)}finally{saving.value=false}}
const requirements=(item:TipoTransaccion)=>[{on:item.orden_compra,label:'Orden de compra'},{on:item.pedido,label:'Pedido'},{on:item.documento,label:'Documento'},{on:item.requiere_asiento_contable,label:'Asiento contable'},{on:item.requiere_almacen_destino,label:'Almacén destino'}].filter(x=>x.on),message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.';onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Almacén / Tipos de transacción</nav><header class="hero"><div class="mark">TX</div><div><small>MIA · CONFIGURACIÓN</small><h1>Tipos de transacción</h1><p>Configura las reglas de validación para los movimientos de almacén.</p></div><b>{{total}} tipos</b><button @click="open()">+ Agregar transacción</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="filters"><input v-model.trim="criterio" placeholder="Buscar por nombre de transacción" @keyup.enter="load(1)"><button @click="load(1)">Buscar</button><button class="soft" @click="criterio='';load(1)">Limpiar</button></section><div v-if="loading" class="empty">Cargando transacciones…</div><div v-else-if="!rows.length" class="empty">No se encontraron tipos de transacción.</div>
<section v-else class="cards"><article v-for="item in rows" :key="item.id" :class="[item.grupo==='i'?'income':'outcome',{inactive:!item.estado}]"><header><div class="icon">{{item.grupo==='i'?'↘':'↗'}}</div><div><small>TRANSACCIÓN DE {{item.grupo==='i'?'INGRESO':'SALIDA'}}</small><h2>{{item.nombre}}</h2></div><span>{{item.estado?'ACTIVA':'INACTIVA'}}</span></header><section><small>DATOS REQUERIDOS</small><div class="tags"><em v-for="rule in requirements(item)" :key="rule.label">✓ {{rule.label}}</em><em v-if="!requirements(item).length" class="none">Sin requisitos adicionales</em></div></section><footer><span v-if="item.documentos_count">{{item.documentos_count}} documentos asociados</span><button @click="open(item)">Modificar</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>REGLAS DE MOVIMIENTO</small><h2>{{editing?'Modificar':'Registrar'}} tipo de transacción</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Tipo de transacción *<select v-model="form.grupo"><option value="">Seleccione</option><option value="i">Ingreso</option><option value="s">Salida</option></select></label><label>Nombre *<input v-model.trim="form.nombre" maxlength="255"></label></div><section class="rules"><h3>Información obligatoria para utilizar esta transacción</h3><label><input v-model="form.orden_compra" type="checkbox"> Requiere orden de compra</label><label><input v-model="form.pedido" type="checkbox"> Requiere pedido</label><label><input v-model="form.documento" type="checkbox"> Requiere documento de referencia</label><label><input v-model="form.requiere_almacen_destino" type="checkbox"> Requiere almacén de destino</label><label><input v-model="form.requiere_asiento_contable" type="checkbox"> Requiere asiento contable</label><label><input v-model="form.estado" type="checkbox"> Transacción activa</label></section><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar transacción'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#d64f83;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:700}.hero small,.cards small,.dialog small{color:var(--accent);font-size:.49rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero>b{margin-left:auto;font-size:.55rem}.hero button,.filters button,.pages button,.dialog button{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.53rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.filters{margin-top:11px;padding:11px;display:flex;gap:6px;border-radius:9px;background:#fff}.filters input{flex:1}.soft{color:#64727a!important;background:#edf1f3!important}input,select{width:100%;box-sizing:border-box;padding:8px;border:1px solid #d9e0e3;border-radius:6px;font:inherit;font-size:.56rem}.empty{margin-top:11px;padding:45px;text-align:center;background:#fff;font-size:.6rem}.cards{margin-top:11px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{padding:13px;border:1px solid #e0e5e7;border-top:4px solid #2d9b68;border-radius:9px;background:#fff}.cards article.outcome{border-top-color:#e18d39}.cards article.inactive{opacity:.65;border-top-color:#9da7ac}.cards article>header{display:flex;align-items:center;gap:8px}.icon{width:36px;height:36px;display:grid;place-items:center;border-radius:8px;color:#fff;background:#2d9b68}.outcome .icon{background:#e18d39}.cards h2{margin:2px 0;font-size:.7rem}.cards header span{margin-left:auto;padding:4px 6px;border-radius:9px;color:#287154;background:#e7f7ef;font-size:.45rem}.inactive header span{color:#68767d;background:#edf0f2}.cards>article>section{margin:12px 0}.tags{margin-top:6px;display:flex;flex-wrap:wrap;gap:5px}.tags em{padding:4px 6px;border-radius:8px;color:#35667c;background:#eaf4f8;font-size:.46rem;font-style:normal}.tags .none{color:#78858b;background:#f0f2f3}.cards footer{display:flex;align-items:center;border-top:1px solid #edf0f1;padding-top:9px}.cards footer span{font-size:.47rem}.cards footer button{margin-left:auto;border:0;color:var(--accent);background:none;font-size:.5rem}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(700px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog h2{margin:2px 0 13px;font-size:1rem}.dialog>header button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.dialog label{font-size:.52rem}.dialog label input,.dialog label select{margin-top:4px}.rules{margin:12px 0;padding:12px;display:grid;grid-template-columns:1fr 1fr;gap:8px;border-radius:8px;background:#f5f7f8}.rules h3{grid-column:1/-1;margin:0 0 3px;font-size:.58rem}.rules label{display:flex;gap:6px;align-items:center}.rules input{width:auto;margin:0!important}.dialog>footer{display:flex;justify-content:flex-end;gap:6px}@media(max-width:850px){.hero{flex-wrap:wrap}.hero>b{margin-left:0}.cards,.grid,.rules{grid-template-columns:1fr}.rules h3{grid-column:auto}}
</style>
